1	import { describe, it, expect, afterEach } from "vitest";
2	import http from "node:http";
3	import { readFileSync } from "node:fs";
4	import path from "node:path";
5	import { Ajv2020 } from "ajv/dist/2020.js";
6	import addFormats from "ajv-formats";
7	import { sendCardReturnedToSpineBestEffort, CardReturnedParams } from "../src/server/sendCardReturned";
8	
9	const CONTRACTS_ROOT = path.join(process.cwd(), "..", "..", "contracts");
10	function loadSchema(relativePath: string): object {
11	  return JSON.parse(readFileSync(path.join(CONTRACTS_ROOT, relativePath), "utf8"));
12	}
13	const ajv = new Ajv2020({ allErrors: true, strict: false });
14	addFormats(ajv);
15	const validateEnvelope = ajv.compile(loadSchema("envelope.v1.json"));
16	const validateCardReturnedPayload = ajv.compile(loadSchema("payloads/card.returned.v1.json"));
17	
18	/** A minimal fake Spine standing in for `POST /tables/:tableId/events`. */
19	function createFakeSpineServer() {
20	  const receivedRequests: { path: string; body: unknown }[] = [];
21	  let respondWithStatus = 201;
22	
23	  const server = http.createServer((req, res) => {
24	    let raw = "";
25	    req.on("data", (chunk) => (raw += chunk));
26	    req.on("end", () => {
27	      receivedRequests.push({ path: req.url ?? "", body: raw ? JSON.parse(raw) : undefined });
28	      res.writeHead(respondWithStatus, { "content-type": "application/json" });
29	      res.end(JSON.stringify({ ok: respondWithStatus < 400 }));
30	    });
31	  });
32	
33	  return {
34	    receivedRequests,
35	    failWith(status: number): void {
36	      respondWithStatus = status;
37	    },
38	    listen(): Promise<number> {
39	      return new Promise((resolve) => {
40	        server.listen(0, () => {
41	          const address = server.address();
42	          resolve(typeof address === "object" && address ? address.port : 0);
43	        });
44	      });
45	    },
46	    close(): Promise<void> {
47	      return new Promise((resolve) => server.close(() => resolve()));
48	    },
49	  };
50	}
51	
52	const baseParams: CardReturnedParams = {
53	  tableId: "friday-night-abc12345",
54	  seatId: "seat-0000001",
55	  playerName: "Jess",
56	  scryfallId: "11111111-1111-4111-8111-111111111111",
57	  gameCardIndex: 3,
58	};
59	
60	describe("sendCardReturnedToSpineBestEffort", () => {
61	  let fakeServer: ReturnType<typeof createFakeSpineServer> | undefined;
62	
63	  afterEach(async () => {
64	    await fakeServer?.close();
65	    fakeServer = undefined;
66	  });
67	
68	  it("POSTs a card.returned.v1 envelope to the Spine's generic events endpoint", async () => {
69	    fakeServer = createFakeSpineServer();
70	    const port = await fakeServer.listen();
71	
72	    await sendCardReturnedToSpineBestEffort(baseParams, `http://localhost:${port}`);
73	
74	    expect(fakeServer.receivedRequests).toHaveLength(1);
75	    const { path, body } = fakeServer.receivedRequests[0] as { path: string; body: any };
76	    expect(path).toBe(`/tables/${baseParams.tableId}/events`);
77	    expect(body.name).toBe("card.returned");
78	    expect(body.tableId).toBe(baseParams.tableId);
79	    expect(body.occurredIn).toBe("tabletop");
80	    expect(body.significance).toBe("domain");
81	    expect(body.schemaVersion).toBe(1);
82	    expect(body.initiator).toEqual({ seatId: baseParams.seatId, playerName: baseParams.playerName });
83	    expect(body.payload).toEqual({
84	      card: { scryfallId: baseParams.scryfallId },
85	      gameCardIndex: baseParams.gameCardIndex,
86	      seat: baseParams.seatId,
87	    });
88	    expect(typeof body.id).toBe("string");
89	
90	    expect(validateEnvelope(body)).toBe(true);
91	    expect(validateCardReturnedPayload(body.payload)).toBe(true);
92	  });
93	
94	  it("carries an optional fromZone when given", async () => {
95	    fakeServer = createFakeSpineServer();
96	    const port = await fakeServer.listen();
97	
98	    await sendCardReturnedToSpineBestEffort({ ...baseParams, fromZone: "battlefield" }, `http://localhost:${port}`);
99	
100	    const { body } = fakeServer.receivedRequests[0] as { body: any };
101	    expect(body.payload.fromZone).toBe("battlefield");
102	  });
103	
104	  it("never throws when the Spine is down — best-effort", async () => {
105	    await expect(sendCardReturnedToSpineBestEffort(baseParams, "http://localhost:1")).resolves.toBeUndefined();
106	  });
107	
108	  it("never throws when the Spine rejects the event — best-effort", async () => {
109	    fakeServer = createFakeSpineServer();
110	    fakeServer.failWith(500);
111	    const port = await fakeServer.listen();
112	
113	    await expect(sendCardReturnedToSpineBestEffort(baseParams, `http://localhost:${port}`)).resolves.toBeUndefined();
114	  });
115	});
